//! The resume workloads (`docs/performance.md`, "Budgets"): a session of
//! 20,000 tokens, and one of 2,000,000 tokens that has handed off 7 times,
//! each generated by the binary under test in a home of its own, then
//! resumed with one prompt over a `full` connection: peak RSS once that
//! turn completes.

use fakes::Response;
use serde_json::{Value, json};

use crate::busy::{READY, TURN, count, expect, filler, in_home, read_log, session, text_reply};
use crate::home::Home;
use crate::idle::{Ctx, Samples, Workload};
use crate::linux;
use crate::run::{Client, Session};

pub(crate) const WORKLOADS: [Workload; 2] = [
    Workload {
        name: "resume 20,000 tokens",
        timing: false,
        run: |ctx, notes| resume(ctx, &SMALL, notes),
    },
    Workload {
        name: "resume 2,000,000 tokens",
        timing: false,
        run: |ctx, notes| resume(ctx, &LARGE, notes),
    },
];

/// A session to resume: its turns, each one reply of `reply_bytes`, with a
/// `handoff` driver command after each of the first `handoffs` turns.
pub(crate) struct Fixture {
    pub(crate) metric: &'static str,
    pub(crate) turns: usize,
    pub(crate) reply_bytes: usize,
    pub(crate) handoffs: usize,
}

pub(crate) const SMALL: Fixture = Fixture {
    metric: "resume_20k_rss_kib",
    turns: 1,
    reply_bytes: 80_000,
    handoffs: 0,
};

pub(crate) const LARGE: Fixture = Fixture {
    metric: "resume_2m_rss_kib",
    turns: 8,
    reply_bytes: 1_000_000,
    handoffs: 7,
};

/// The note the model writes at each handoff.
const NOTE: &str = "the work so far is in the session log";

/// The reply to the prompt the measured run sends.
const LAST_REPLY: &str = "resumed";

impl Fixture {
    /// The provider's replies in the order the session asks for them: each
    /// turn's reply, a note after each handed-off turn, then the measured
    /// run's reply. Each reports the context it was asked over, which a
    /// handoff restarts from the note, so no automatic handoff runs.
    pub(crate) fn script(&self) -> Vec<Response> {
        let mut script = Vec::new();
        let mut context = 0;
        for turn in 0..self.turns {
            context += prompt(turn).len();
            let reply = filler(self.reply_bytes, u64::try_from(turn).unwrap_or_default());
            script.push(text_reply(&reply, context));
            context += reply.len();
            if turn < self.handoffs {
                script.push(text_reply(NOTE, context));
                context = NOTE.len();
            }
        }
        script.push(text_reply(LAST_REPLY, context));
        script
    }
}

fn prompt(turn: usize) -> String {
    format!("turn {turn}")
}

/// A command line for the socket.
fn command(id: &str, name: &str, args: &Value) -> String {
    json!({"id": id, "command": name, "args": args}).to_string()
}

/// Sends `line`, whose id is `id`, then reads until its acknowledgement
/// and the `turn_completed` after it, waiting at most [`TURN`].
fn run_turn(ctx: &Ctx<'_>, client: &mut Client, id: &str, line: &str) -> Result<(), String> {
    client.send(line)?;
    let until = ctx.clock.now() + TURN;
    let what = format!("the turn_completed of {id}");
    let mut accepted = false;
    loop {
        let line = client.line(ctx.clock, until, &what)?;
        let kind = line.get("kind").and_then(Value::as_str);
        if line.pointer("/payload/command_id") == Some(&json!(id)) {
            if kind != Some("command_accepted") {
                return Err(format!("{id} was not accepted: {line}"));
            }
            accepted = true;
        } else if accepted && kind == Some("turn_completed") {
            return Ok(());
        }
    }
}

/// Connects to the session's socket and subscribes at `full`.
fn subscribe(ctx: &Ctx<'_>, home: &Home, id: &str) -> Result<Client, String> {
    let mut client = Client::connect(&home.socket(id))?;
    client.send(&command("c_sub", "subscribe", &json!({"level": "full"})))?;
    let until = ctx.clock.now() + READY;
    loop {
        let line = client.line(ctx.clock, until, "the subscribe acknowledgement")?;
        if line.pointer("/payload/command_id") == Some(&json!("c_sub")) {
            return Ok(client);
        }
    }
}

/// Writes the fixture's turns and handoffs through a session of its own,
/// closes it, and checks every handoff completed and none was automatic.
fn generate(
    ctx: &Ctx<'_>,
    home: &Home,
    fixture: &Fixture,
    id: &str,
    notes: &mut Vec<String>,
) -> Result<(), String> {
    let session = Session::spawn(&mut session(ctx, home, id, &[]), ctx.clock)?;
    let written = (|| {
        session.wait_started(ctx.clock, ctx.clock.now() + READY)?;
        let mut client = subscribe(ctx, home, id)?;
        for turn in 0..fixture.turns {
            let prompt_id = format!("c_p{turn}");
            let content = json!({"content": [{"type": "text", "text": prompt(turn)}]});
            run_turn(
                ctx,
                &mut client,
                &prompt_id,
                &command(&prompt_id, "prompt", &content),
            )?;
            if turn < fixture.handoffs {
                let handoff_id = format!("c_h{turn}");
                let line = command(&handoff_id, "handoff", &json!({}));
                run_turn(ctx, &mut client, &handoff_id, &line)?;
            }
        }
        client.send(&command("c_close", "close", &json!({})))
    })();
    let mut proc = session.proc;
    let closed = written.and_then(|()| proc.exits(ctx.clock, READY));
    let stopped = proc.stop(ctx.clock);
    if !closed? {
        notes.push("the fixture session did not exit on close".to_owned());
    }
    stopped?;
    let lines = read_log(home, id)?;
    expect(
        notes,
        "completed handoffs",
        count(&lines, "handoff_completed", "outcome", "completed"),
        fixture.handoffs,
    );
    expect(
        notes,
        "automatic handoffs",
        count(&lines, "handoff_started", "trigger", "auto"),
        0,
    );
    Ok(())
}

/// Generates the fixture, then resumes it, sends one prompt over a `full`
/// connection and reads the peak RSS once that turn completes.
fn resume(ctx: &Ctx<'_>, fixture: &Fixture, notes: &mut Vec<String>) -> Result<Samples, String> {
    let script = fixture.script();
    let requests = script.len();
    in_home(Home::scripted(ctx.home.fiber(), script)?, |home| {
        let id = doors::mint("s_");
        generate(ctx, home, fixture, &id, notes)?;
        let session = Session::spawn(&mut session(ctx, home, &id, &["--resume"]), ctx.clock)?;
        let pid = session.proc.pid();
        let measured = session
            .line(ctx.clock, ctx.clock.now() + READY, "the first stdout line")
            .and_then(|_| subscribe(ctx, home, &id))
            .and_then(|mut client| {
                let content = json!({"content": [{"type": "text", "text": "go on"}]});
                run_turn(
                    ctx,
                    &mut client,
                    "c_go",
                    &command("c_go", "prompt", &content),
                )
            })
            .and_then(|()| linux::peak_rss_kib(pid));
        let stopped = session.proc.stop(ctx.clock);
        let rss = measured?;
        stopped?;
        expect(
            notes,
            "model requests",
            home.server().requests().len(),
            requests,
        );
        Ok(vec![(fixture.metric, json!(rss))])
    })
}

